    saveChatInfo(chat) {
      return this.chatSvc.saveChatInfo(chat || this.chat)
    },
    replaceEmoji({ emoji }) {
      const { caretIndex, word } = this.cursorWord
      const text = this.$refs.inputBox?.getEditorText() ?? ''
      const left = text.slice(0, caretIndex - word.length)
